async def act(page):
    """
    From the current Dashboard, navigate to the CMS pages listing, open the "About us" CMS page edit
    screen, set the Page Title to "Secret", and save the page.

    Notes:
    - Uses accessibility-based selectors (.get_by_role) and prefers full-path access via the form when
      interacting with controls that belong to the form.
    - Uses a relative goto to the CMS pages index.
    - The Save click (which is expected to navigate/persist changes) is the final action.
    """

    # Knowledge-base functions: none are available in the environment, so all actions use Playwright APIs.

    # 1) Go to the CMS pages listing (relative URL)
    await page.goto('/index.php/admin/cms_page/index/')
    await page.wait_for_load_state('networkidle')

    # 2) Locate the "About us" link and obtain its href
    about_href = None
    for name in ('About us', 'About Us', 'About'):
        try:
            candidate = page.get_by_role('link', name=name)
            if await candidate.count() > 0:
                about_href = await candidate.first().get_attribute('href')
                if about_href:
                    break
        except Exception:
            continue

    # Fallback: scan all links and inspect aria-label or inner text for substring 'about'
    if not about_href:
        all_links = page.get_by_role('link')
        total = await all_links.count()
        for i in range(total):
            l = all_links.nth(i)
            name = await l.get_attribute('aria-label')
            if not name:
                try:
                    name = (await l.inner_text()).strip()
                except Exception:
                    name = ''
            if name and 'about' in name.lower():
                href = await l.get_attribute('href')
                if href:
                    about_href = href
                    break

    if not about_href:
        raise RuntimeError('Could not locate the About us link on the CMS pages listing.')

    # 3) Navigate to the About us edit page (use href to avoid clicking navigation earlier)
    await page.goto(about_href)
    await page.wait_for_load_state('networkidle')

    # 4) Find the Page Title textbox (prefer full-path: form -> textbox) and fill with 'Secret'
    title_candidates = ('Page Title', 'Title', 'page title', 'page_title')
    title_set = False

    form_locator = page.get_by_role('form')
    form = form_locator.first() if await form_locator.count() > 0 else None

    if form:
        for tname in title_candidates:
            try:
                tb = form.get_by_role('textbox', name=tname)
                if await tb.count() > 0:
                    await tb.first().fill('Secret')
                    title_set = True
                    break
            except Exception:
                continue
        if not title_set:
            try:
                tbs = form.get_by_role('textbox')
                if await tbs.count() > 0:
                    await tbs.first().fill('Secret')
                    title_set = True
            except Exception:
                title_set = False
    else:
        # No form found; try document-level textbox selectors
        for tname in title_candidates:
            try:
                tb = page.get_by_role('textbox', name=tname)
                if await tb.count() > 0:
                    await tb.first().fill('Secret')
                    title_set = True
                    break
            except Exception:
                continue
        if not title_set:
            try:
                tbs = page.get_by_role('textbox')
                if await tbs.count() > 0:
                    await tbs.first().fill('Secret')
                    title_set = True
            except Exception:
                title_set = False

    if not title_set:
        raise RuntimeError('Could not find a Page Title textbox to set.')

    # 5) Click the Save button inside the form (full-path) or fallback to a document-level Save button.
    # This click is expected to navigate/save and must be the final action.
    save_clicked = False
    if form:
        for btn_name in ('Save Page', 'Save'):
            try:
                btn = form.get_by_role('button', name=btn_name)
                if await btn.count() > 0:
                    await btn.first().click()
                    save_clicked = True
                    break
            except Exception:
                continue

    if not save_clicked:
        for btn_name in ('Save Page', 'Save'):
            try:
                btn = page.get_by_role('button', name=btn_name)
                if await btn.count() > 0:
                    await btn.first().click()
                    save_clicked = True
                    break
            except Exception:
                continue

    if not save_clicked:
        raise RuntimeError('Could not find any Save button to click.')

    # After clicking Save (expected navigation/state change), wait for completion
    await page.wait_for_load_state('networkidle')

